/*
 * A231874  Elements of the segmented integer compositions sub-operad SComp of
 *          TN_3 generated by 00, 01, 02.
 * https://oeis.org/A231874
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the nth lexicographically ordered word over {1,2,3}
 *            starting with 1, interpreted as a decimal integer
 * Range:     u8 n <= 13, u16 n <= 40, u32 n <= 40, u64 n <= 40, u128 n <= 40,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n) {
    /* Find the length L of the word.  For L>=1 the number of words of
       length <= L is S(L) = 1 + 3 + 3^2 + … + 3^(L-1) = (3^L - 1)/2. */
    idx_t L = 1;
    seq_t pow = 1;          /* 3^(L-1) */
    seq_t sum = 1;          /* S(L) */

    /* Increase L until S(L) >= n. */
    while (sum < n) {
        pow *= 3;           /* now pow = 3^L */
        sum += pow;         /* now sum = S(L+1) */
        ++L;
    }

    /* Compute the offset of the nth word within the block of length L
       words.  The total number of words of shorter length is
       sum - pow. */
    seq_t offset = (seq_t)(n - 1) - (sum - pow);

    /* Build the decimal value.  The leading digit is always '1'. */
    seq_t val = 1;
    idx_t len = L - 1;     /* number of remaining digits */

    /* Extract the base‑3 digits of offset, most significant first.  */
    seq_t digits[64] = {0};          /* freeness for up to 64 digits */
    idx_t pos = len;
    seq_t tmp = offset;
    while (tmp > 0 && pos > 0) {
        --pos;
        digits[pos] = tmp % 3;
        tmp /= 3;
    }

    /* Convert digits (0‑based) to decimal digits (1‑3) and append to val. */
    for (idx_t i = 0; i < len; ++i) {
        seq_t d = digits[i] + 1;     /* map 0→1, 1→2, 2→3 */
        val = val * 10 + d;
    }
    return val;
}
